import { Suspense } from "react"
import Link from "next/link"

import { MonitoringDateFilter } from "@/app/(portal)/admin/live-monitoring/components/monitoring-date-filter"
import { MonitoringPanelSkeleton } from "@/app/(portal)/admin/live-monitoring/components/monitoring-panel-skeleton"

export const dynamic = "force-dynamic"

async function SlowPanel({ from, to }: { from: string; to: string }) {
  await new Promise(resolve => setTimeout(resolve, 1200))
  return <p>Panel {from} to {to}</p>
}

export default async function DebugMonitoringPage({ searchParams }: { searchParams: Promise<{ from?: string; to?: string; variant?: string }> }) {
  const params = await searchParams
  const from = params.from ?? "2026-10-22"
  const to = params.to ?? "2026-10-28"
  const variant = params.variant ?? "both"

  const filter = variant === "nokeys" || variant === "innerkey" || variant === "routekey"
    ? <MonitoringDateFilter from={from} to={to} />
    : <MonitoringDateFilter key={`${from}:${to}`} from={from} to={to} />

  let panel
  if (variant === "innerkey") {
    panel = (
      <Suspense fallback={<MonitoringPanelSkeleton />}>
        <div key={`${from}:${to}`}><SlowPanel from={from} to={to} /></div>
      </Suspense>
    )
  } else if (variant === "routekey") {
    panel = (
      <Suspense key={`${from}:${to}`} fallback={<MonitoringPanelSkeleton />}>
        <SlowPanel from={from} to={to} />
      </Suspense>
    )
  } else if (variant === "nokeys") {
    panel = (
      <Suspense fallback={<MonitoringPanelSkeleton />}>
        <SlowPanel from={from} to={to} />
      </Suspense>
    )
  } else {
    panel = (
      <Suspense key={`${from}:${to}`} fallback={<MonitoringPanelSkeleton />}>
        <SlowPanel from={from} to={to} />
      </Suspense>
    )
  }

  return (
    <div className="flex flex-col gap-4 p-6">
      {filter}
      {panel}
      <Link href="/debug-monitoring?variant=both">Reset variant</Link>
    </div>
  )
}
